<?php require __DIR__.'/includes/bootstrap.php';if(empty($_SESSION['customer_id']))go('login.php');$s=db()->prepare('SELECT order_number,total,status,created_at FROM orders WHERE customer_id=? ORDER BY id DESC');$s->execute([$_SESSION['customer_id']]);$orders=$s->fetchAll();?><!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>طلباتي</title><link rel="stylesheet" href="assets/css/store.css"></head><body><?php include __DIR__.'/includes/nav.php';?><main class="inner"><h1>طلباتي</h1><?php if(!$orders):?><p>لا توجد طلبات مرتبطة بحسابك حتى الآن.</p><?php else:?><div class="table-wrap"><table><tr><th>رقم الطلب</th><th>الإجمالي</th><th>الحالة</th><th>التاريخ</th></tr><?php foreach($orders as $o):?><tr><td><?=h($o['order_number'])?></td><td><?=money($o['total'])?></td><td><?=h($o['status'])?></td><td><?=h($o['created_at'])?></td></tr><?php endforeach?></table></div><?php endif?></main><?php include __DIR__.'/includes/footer.php';?></body></html>